<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { useLabSession } from '../session'
import { coreSceneAdapter,type SceneWorkbenchAdapter } from '../sceneAdapter'
import { nodeById,nodePath,kindLabels } from '../sceneGraph'
import SceneView from './SceneView.vue'
import SceneTreePanel from './SceneTreePanel.vue'
import { Layers,MoreHorizontal,Pause,Play,SkipForward,FastForward,RotateCcw,Expand,ArrowUpLeft,LocateFixed } from 'lucide-vue-next'
const props=defineProps<{adapter?:SceneWorkbenchAdapter}>(),lab=props.adapter??coreSceneAdapter(useLabSession()),root=ref<HTMLElement>(),viewer=ref<InstanceType<typeof SceneView>>(),treeOpen=ref(true),moreOpen=ref(false),compact=ref(false),fullscreen=ref(false)
let observer:ResizeObserver,userToggled=false,previousOverflow='',previousFocus:HTMLElement|null=null
const path=computed(()=>nodePath(lab.sceneLayout,lab.sceneView.levelId)),selected=computed(()=>nodeById(lab.sceneLayout,lab.sceneView.selectedId)!)
const canControl=computed(()=>!!lab.simulation?.activeId&&!lab.simulation.complete&&lab.simulation.currentMatches)
function control(action:'pause'|'resume'|'step'|'finish'){if(canControl.value)lab.simulation?.control(action)}
function toggleTree(){userToggled=true;treeOpen.value=!treeOpen.value;moreOpen.value=false}
function enterSelected(){lab.enterSceneNode(selected.value.id);if(compact.value)treeOpen.value=false}
function locate(id:'tank'|'pump'|'exchanger'){lab.locateEquipment(id);if(compact.value)treeOpen.value=false}
function publishFullscreen(){document.dispatchEvent(new Event('scene-workbench-fullscreenchange'))}
function leaveScreen(){if(!fullscreen.value)return;fullscreen.value=false;document.body.style.overflow=previousOverflow;nextTick(()=>{publishFullscreen();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true})})}
async function screen(){if(fullscreen.value){leaveScreen();return}previousOverflow=document.body.style.overflow;previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;fullscreen.value=true;document.body.style.overflow='hidden';await nextTick();publishFullscreen();root.value?.querySelector<HTMLElement>('[aria-label="全屏场景"]')?.focus({preventScroll:true});viewer.value?.resetView()}
function escape(e:KeyboardEvent){if(e.key==='Escape'){leaveScreen();treeOpen.value=compact.value?false:treeOpen.value;moreOpen.value=false}}
function navigationRequest(e:Event){const action=(e as CustomEvent<string>).detail;if(action==='exit-fullscreen'){leaveScreen()}else if(action==='open-tree'){userToggled=true;treeOpen.value=true;moreOpen.value=false}else if(action==='locate-experiment'){lab.locateExperiment();treeOpen.value=compact.value?false:treeOpen.value}}
watch(()=>lab.sceneView.levelId,()=>{if(compact.value)treeOpen.value=false})
onMounted(()=>{observer=new ResizeObserver(()=>{compact.value=(root.value?.clientWidth??0)<820;if(!userToggled)treeOpen.value=!compact.value});observer.observe(root.value!);document.addEventListener('keydown',escape);root.value!.addEventListener('scene-guide',navigationRequest)})
onBeforeUnmount(()=>{leaveScreen();observer?.disconnect();document.removeEventListener('keydown',escape);root.value?.removeEventListener('scene-guide',navigationRequest)})
async function reset(){lab.restoreSceneVisibility();await nextTick();viewer.value?.resetView()}
</script>
<template><section ref="root" class="scene-workbench" :class="{compact,'tree-open':treeOpen,'is-fullscreen':fullscreen}" data-guide="simulation" aria-label="16比9三维仿真工作区"><h2 class="scene-sr-only">设备数据与规则仿真</h2><div class="scene-window-toolbar"><button class="scene-icon" aria-label="切换场景层级面板" :aria-expanded="treeOpen" @click="toggleTree"><Layers :size="16"/></button><nav class="scene-breadcrumb" aria-label="三维场景路径"><button v-for="(n,i) in path" :key="n.id" :title="n.name" @click="lab.enterSceneNode(n.id)"><span v-if="i">/</span>{{ compact&&i<path.length-1?kindLabels[n.kind]:n.name }}</button></nav><div class="scene-simulation-controls"><button class="scene-start" data-guide-focus :disabled="!lab.primary.enabled" :title="lab.primary.reason" @click="lab.primary.run">{{ lab.primary.label }}</button><slot name="toolbar-actions" :adapter="lab"/><button class="scene-icon" :aria-label="lab.simulation?.running?'暂停仿真':'继续仿真'" :title="lab.simulationUnavailableReason||(lab.simulation?.running?'暂停仿真':'继续仿真')" :disabled="!canControl" @click="control(lab.simulation?.running?'pause':'resume')"><Pause v-if="lab.simulation?.running" :size="15"/><Play v-else :size="15"/></button><template v-if="!compact"><button class="scene-icon" aria-label="前进1秒" :title="lab.simulationUnavailableReason||'前进1秒'" :disabled="!canControl" @click="control('step')"><SkipForward :size="16"/></button><button class="scene-icon" aria-label="快速完成本轮" :title="lab.simulationUnavailableReason||'快速完成本轮'" :disabled="!canControl" @click="control('finish')"><FastForward :size="16"/></button></template><time>{{ lab.clockLabel }}</time><button class="scene-icon" aria-label="三维窗口更多操作" :aria-expanded="moreOpen" @click="moreOpen=!moreOpen;treeOpen=compact&&moreOpen?false:treeOpen"><MoreHorizontal :size="17"/></button></div></div>
<div v-if="moreOpen" class="scene-more-panel"><template v-if="compact"><button :disabled="!canControl" @click="control('step')">前进1秒</button><button :disabled="!canControl" @click="control('finish')">快速完成本轮</button></template><button @click="lab.locateExperiment();moreOpen=false">定位当前实验</button><button @click="reset();moreOpen=false">恢复默认视角</button><p>{{ lab.description }}</p><p v-if="lab.simulationUnavailableReason">{{ lab.simulationUnavailableReason }}</p><p>{{ lab.recordSummary }}</p></div>
<div class="scene-window-body" data-guide="scene-navigation"><div v-if="compact&&treeOpen" class="scene-tree-shade" @click="treeOpen=false"></div><SceneTreePanel v-if="treeOpen" :adapter="lab"/><div class="scene-viewer-cell" data-guide="scene"><SceneView ref="viewer" :adapter="lab"/><slot name="scene-overlay" :adapter="lab"/><div class="scene-view-status"><span :class="{'scene-stale':lab.simulation?.activeId&&!lab.simulation.currentMatches}">{{ lab.stateLabel }}</span></div><button v-if="(selected.kind==='area'||selected.kind==='workshop')&&selected.id!==lab.sceneView.levelId" class="scene-enter-selected" @click="enterSelected">进入{{ kindLabels[selected.kind] }} →</button></div></div>
<div class="scene-window-bottom"><div class="scene-equipment-shortcuts"><button v-for="a in lab.assets" :key="a.id" :class="{active:lab.sceneView.selectedId==='model-'+a.id}" :aria-label="'定位'+a.name+'模型'" @click="locate(a.id)">{{ a.name }}</button></div><div class="scene-navigation-tools"><button class="scene-icon" aria-label="返回三维上级" title="返回上级" :disabled="lab.sceneView.levelId==='factory'" @click="lab.goSceneUp"><ArrowUpLeft :size="15"/></button><button class="scene-icon" aria-label="定位当前实验" title="定位当前实验" @click="lab.locateExperiment()"><LocateFixed :size="15"/></button><button class="scene-icon" aria-label="恢复默认视角" title="恢复默认视角" @click="reset"><RotateCcw :size="15"/></button><button class="scene-icon" aria-label="全屏场景" title="全屏场景" @click="screen"><Expand :size="15"/></button></div></div></section></template>
